#include <stdio.h>
#include <stdlib.h>
#include <math.h>
int main(){
 FILE*f=fopen("/app/gpt2-124M.ckpt","rb");
 long n=124439808L;
 float*buf=malloc(n*4);
 fread(buf,4,n,f);fclose(f);
 // Print stats for every 768-block in layer 0 (first 7,087,872 floats)
 for(long i=0;i<7087872L;i+=768){
  double s=0,v=0;
  for(int j=0;j<768;j++)s+=buf[i+j];
  double m=s/768.0;
  for(int j=0;j<768;j++){double d=buf[i+j]-m;v+=d*d;}
  double sd=sqrt(v/768.0);
  // Only print "interesting" blocks: near-zero mean (bias), positive mean (gain), or first few/last few
  if(i<1536||i>2360064||(fabs(m)<0.05&&sd<0.2)||(m>0.1&&sd<0.1))
   printf("off=%ld (%.0f) m=%.4f sd=%.4f first=%.4f\n",i,i*4.0,m,sd,buf[i]);
 }
 // Also print stats for larger blocks at known boundaries
 printf("\nLarge block stats:\n");
 long offsets[]={0,2304,1771776,1772544,2362368,2363136,2363904,2364672,2365440,2368128,4724736,4725504,4726272,7086048,7086816};
 long sizes[]={2304,1769472,768,589824,768,768,768,768,3072,2359296,768,2359296,768,1536,1536};
 for(int k=0;k<15;k++){
  long o=offsets[k],sz=sizes[k];
  double s=0;
  for(long j=0;j<sz;j++)s+=buf[o+j];
  double m=s/(double)sz;
  double v=0;
  for(long j=0;j<sz;j++){double d=buf[o+j]-m;v+=d*d;}
  printf("off=%ld size=%ld m=%.6f sd=%.6f\n",o,sz,m,sqrt(v/sz));
 }
 return 0;
}
